INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66676685', 66676685, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Komunikasi Publik Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 247800000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Konsultan Komunikasi Publik (Public Communication Specialist) dilakukan dengan tujuan untuk penerapan strategi komunikasi TPB/SDGs, yang melingkupi desain, manajemen, implementasi strategi komunikasi dan publikasi TPB/SDGs, dibawah koordinasi langsung koordinator Tenaga Ahli Sekretariat TPB/SDGs.', 'Adapun ruang lingkup pekerjaan untuk Komunikasi Publik Spesialis dalam membantu Koordinator Tim Ahli meliputi: Bertanggung jawab dalam perencanaan, strategi, dan intervensi komunikasi TPB/SDGs; Pengembangan, pelaksanaan, dan pembaharuan strategi media dan komunikasi TPB/SDGs Indonesia, termasuk rencana komunikasi tanggap darurat Kolaborasi dengan seluruh staf Sekretariat TPB/SDGs untuk pengembangan dan penerapan strategi komunikasi yang efektif berdasarkan target khalayak Penulisan, pengeditan, dan pendistribusian konten, termasuk publikasi, siaran pers, konten situs web, laporan tahunan, pidato, dan materi lainnya untuk mengkomunikasikan kegiatan TPB/SDGs Kolaborasi dengan pilar TPB/SDGs untuk pengembangan pesan media sosial dalam koordinasi dari TPB/SDGs dan menerapkan intervensi berdasarkan target audiens; Pengembangan artikel/berita/informasi terkait dengan TPB/SDGs; Bekerja sama dengan semua pilar TPB/SDGs dalam pengembangan materi advokasi untuk mendukung pelaksanaan program TPB/SDGs; Bekerja sama dengan Duta TPB/SDGs dalam pengembangan materi advokasi untuk mendukung pelaksanaan program kerja Duta TPB/SDGs; Berkoordinasi dengan program komunikasi dan kehumasan di Kementerian PPN/Bappenas, platform partisipasi lainnya di tingkat pusat dan daerah serta Mitra Pembangunan; Pemeliharaan dan pembaharuan situs web TPB/SDGs Indonesia; Promosi kegiatan dan diseminasi capaian TPB/SDG ke dalam liputan media dan kepada semua pemangku kepentingan; Penyusunan catatan liputan media dan menyusun analisis dan metrik; Kampanye semua materi agar memiliki visibilitas tinggi di media sosial, melalui komunikasi yang konstan, fokus, dan inovatif; Desain semua media komunikasi menggunakan grafis dan publishing software; Membantu tugas-tugas lainnya untuk pelaksanaan SDGs.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2930024);
