INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66675646', 66675646, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Manajer Pilar Pembangunan Sosial Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 696000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Konsultan Manager Pilar Pembangunan Sosial pada Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan (TPB)/ Sustainable Development Goals (SDGs) Tahun Anggaran 2026.', 'Secara umum tujuan kegiatan ini adalah untuk mempersiapkan berbagai dokumen untuk mendorong pelaksanaan pencapaian TPB/SDGs. Secara khusus tujuan kegiatan ini adalah untuk : Melakukan Sosialisasi Peta Jalan SDGs khususnya Pilar Pembangunan Sosial; Melakukan analisis terhadap indikator dan data proyeksi Pilar Pembangunan Sosial dalam Dokumen Peta Jalan (Road Map) TPB/SDGs; Melakukan pemetaan dan analisa indikator TPB/SDGs pada dokumen rancangan RPJMN 2025–2029; Pemutakhiran RAN TPB/SDGs Tahun 2025-2030 khususnya Pilar Pembangunan Sosial; Mempersiapkan penyusunan dan memberi masukan strategis untuk penyusunan Laporan Tahunan Pelaksanaan SDGs 2026; Memantau pelaksanaan Rencana Aksi Nasional (RAN) dan Rencana Aksi Daerah (RAD) TPB/SDGs melalui koordinasi intensif dengan K/L terkait; Fasilitasi daerah dalam penyusunan Rencana Aksi Daerah Tujuan Pembangunan Berkelanjutan (RAD-TPB/SDGs); Fasilitasi Organisasi non pemerintah dalam penyusunan Rencana Aksi Daerah Tujuan Pembangunan Berkelanjutan (RAD-TPB/SDGs); Menganalisa data dan informasi untuk indikator Pilar Pembangunan Sosial; Menyusun, menyempurnakan dan memberikan masukan substansi atas indikator yang dikembangkan dalam Metadata Pilar Pembangunan Sosial; Fasilitasi Pemerintah Daerah Provinsi/Kabupaten/Kota dalam pemantauan, evaluasi, dan pelaporan pelaksanaan pencapaian TPB/SDGs; Fasilitasi organisasi nonpemerintah dalam penyusunan pemantauan, evaluasi, dan pelaporan pelaksanaan pencapaian TPB/SDGs; Menyusun materi dan bahan-bahan untuk pertemuan/workshop/seminar terkait TPB/SDGs baik untuk kegiatan di dalam negeri maupun di luar negeri; Menyusun diseminasi dan informasi tentang TPB/SDGs kepada berbagai stakeholders (Pemerintah, DPR, pihak swasta, filantropi, CSOs, media, akademisi, baik di tingkat nasional maupun daerah); Pelaksanaan penugasan lainnya di Sekretariat TPB/SDGs, sesuai arahan Ketua Tim Pelaksana TPB/SDGs dan atau Kepala Sekretariat TPB/SDGs.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2930492);
