INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66675819', 66675819, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Manajer Pilar Pembangunan Ekonomi Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 696000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Konsultan Manager Pilar Pembangunan Ekonomi pada Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs) Tahun Anggaran 2026.', 'Secara umum tujuan kegiatan ini adalah untuk mempersiapkan berbagai dokumen untuk mendorong pelaksanaan pencapaian TPB/SDGs. Secara khusus tujuan kegiatan ini adalah untuk: Perumusan Metadata Indikator SDGs versi III, secara inklusif; Penyusunan Dokumen Rencana Aksi Nasional TPB/SDGs 2025 – 2029 secara Inklusif, khususnya Pilar Pembangunan Ekonomi; Pemutakhiran Peta Jalan SDGs 2017-2030 secara inklusif, khususnya Pilar Pembangunan Ekonomi; Fasilitasi daerah dalam penyusunan Rencana Aksi Daerah Tujuan Pembangunan Berkelanjutan (RAD-TPB/SDGs), secara inklusif; Koordinasi pengembangan dan pemeliharaan jejaring dengan berbagai sumber pendanaan baik dalam maupun luar negeri Fasilitasi koordinasi Kerjasama Non-State Actors dalam pelaksanaan SDGs (Organisasi kemasyarakatan, Dunia Usaha, Akademisi dan Media); Memantau pelaksanaan Rencana Aksi Nasional (RAN) dan Rencana Aksi Daerah (RAD) TPB/SDGs melalui koordinasi intensif dengan K/L terkait; Fasilitasi Pemerintah Daerah Provinsi/Kabupaten/Kota dalam pemantauan, evaluasi, dan pelaporan pelaksanaan pencapaian TPB/SDGs; Fasilitasi organisasi nonpemerintah dalam penyusunan pemantauan, evaluasi, dan pelaporan pelaksanaan pencapaian TPB/SDGs; Menyusun materi dan bahan-bahan untuk pertemuan/workshop/seminar terkait TPB/SDGs baik untuk kegiatan di dalam negeri maupun di luar negeri; Menyusun diseminasi dan informasi tentang TPB/SDGs kepada berbagai stakeholders (Pemerintah, DPR, pihak swasta, filantropi, CSOs, media, akademisi, baik di tingkat nasional maupun daerah); Pelaksanaan penugasan lainnya di Sekretariat TPB/SDGs, sesuai arahan Ketua Tim Pelaksana TPB/SDGs dan atau Kepala Sekretariat TPB/SDGs.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2931047);
