INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66683922', 66683922, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Pengujian keamanan dan efektifitas dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 5000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan pelaksanaan pengujian keamanan dan efektivitas produk dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan. Pengujian dilakukan untuk memastikan bahwa produk inovasi pangan olahan yang diajukan telah memenuhi persyaratan keamanan dan efektivitas sesuai standar yang berlaku, sebagai bagian dari proses fasilitasi standardisasi secara menyeluruh. Hasil pengujian ini menjadi dasar ilmiah dalam proses pembahasan dan penetapan standar produk inovasi pangan olahan.', 'Pengujian keamanan dan efektivitas dilaksanakan terhadap sampel produk inovasi pangan olahan yang telah ditetapkan sebagai objek kajian dalam proses fasilitasi standardisasi. Pengujian keamanan meliputi analisis parameter keamanan pangan seperti uji cemaran mikrobiologi, cemaran kimia, dan parameter keamanan lainnya sesuai persyaratan regulasi yang berlaku. Pengujian efektivitas dilakukan untuk membuktikan klaim manfaat produk sesuai dengan peruntukan dan kategori produk yang diajukan. Pengujian dilaksanakan oleh laboratorium yang telah terakreditasi dan kompeten di bidangnya, dengan metode pengujian mengacu pada standar nasional maupun internasional yang relevan. Biaya pengujian dibayarkan berdasarkan kebutuhan riil sesuai jenis dan jumlah parameter uji yang diperlukan, dengan mempertimbangkan efisiensi anggaran dan kesesuaian dengan ketentuan pengadaan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2933076);
