INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66684132', 66684132, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Pelaksanaan Operasional Kegiatan Standardisasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 64295000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan penyediaan belanja bahan dalam rangka mendukung pelaksanaan operasional kegiatan Standardisasi Pangan Olahan. Belanja bahan yang disediakan meliputi pencetakan habis pakai, konsumsi makan siang untuk pertemuan di kantor, serta snack rapat biasa yang diperlukan dalam pelaksanaan rapat dan pertemuan rutin. Penyediaan belanja bahan ini bertujuan untuk memastikan kelancaran pelaksanaan kegiatan operasional standardisasi pangan olahan secara keseluruhan.', '"1. Pencetakan Habis Pakai Biaya pencetakan bahan habis pakai yang diperlukan dalam rangka pelaksanaan operasional kegiatan standardisasi pangan olahan, meliputi antara lain pencetakan dokumen, laporan, bahan paparan, formulir, dan materi pendukung kegiatan lainnya. Pencetakan dilakukan sesuai kebutuhan riil pelaksanaan kegiatan dengan memperhatikan prinsip efisiensi, dan biaya yang dikeluarkan disesuaikan dengan tarif pencetakan yang berlaku. 2. Makan Siang Pertemuan di Kantor Konsumsi makan siang yang disediakan bagi peserta pertemuan/rapat yang diselenggarakan di kantor dalam rangka pelaksanaan operasional kegiatan standardisasi pangan olahan. Makan siang disediakan sesuai jumlah peserta yang hadir dengan menu memenuhi standar kelayakan konsumsi. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan. 3. Snack Rapat Biasa Konsumsi snack yang disediakan bagi peserta rapat biasa dalam rangka mendukung kelancaran pelaksanaan rapat operasional kegiatan standardisasi pangan olahan. Snack disediakan sesuai jumlah peserta yang hadir dalam setiap pelaksanaan rapat. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2933833);
