INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66683925', 66683925, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Paket Meeting Fullday Dalam Kota dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 18200000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Kegiatan ini merupakan penyelenggaraan pertemuan pembahasan dalam format paket meeting fullday dalam kota dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan. Pertemuan dilaksanakan sepanjang hari guna membahas secara mendalam berbagai aspek teknis yang berkaitan dengan proses fasilitasi standardisasi produk inovasi pangan olahan. Penyelenggaraan dalam format fullday dimaksudkan agar pembahasan dapat berlangsung secara komprehensif dan menghasilkan rumusan yang optimal.', 'Paket meeting fullday dalam kota mencakup penyediaan fasilitas ruang pertemuan beserta perlengkapan rapat yang memadai, seperti proyektor, layar, sound system, dan alat tulis kantor. Konsumsi yang disediakan dalam paket ini meliputi makan siang satu kali serta snack/coffee break dua kali, yaitu pada sesi pagi dan sore hari, sesuai dengan standar paket meeting fullday yang berlaku. Fasilitas penyelenggaraan rapat disediakan di hotel atau gedung pertemuan dalam kota yang representatif dan memenuhi standar kelayakan. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/hari paket meeting fullday dalam kota, dan dibayarkan berdasarkan jumlah peserta yang hadir sesuai kebutuhan riil pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2934068);
