INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66683927', 66683927, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 38648000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan penyediaan bahan pendukung dalam rangka pelaksanaan Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan. Bahan yang disediakan meliputi konsumsi rapat berupa makan siang dan snack untuk peserta rapat pembahasan, serta pembelian sampel produk inovasi pangan olahan yang diperlukan sebagai bahan kajian dalam proses standardisasi. Penyediaan bahan ini bertujuan untuk mendukung kelancaran pelaksanaan rapat pembahasan dan proses fasilitasi standardisasi secara keseluruhan.', '1. Makan Siang Rapat Pembahasan Konsumsi makan siang yang disediakan bagi peserta rapat pembahasan dalam rangka fasilitasi standardisasi keamanan, mutu, dan manfaat produk inovasi pangan olahan. Makan siang disediakan sesuai dengan jumlah peserta yang hadir. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan. 2. Snack Rapat Pembahasan Konsumsi snack yang disediakan bagi peserta rapat pembahasan sebagai pendukung kelancaran jalannya rapat. Snack disediakan sesuai dengan jumlah peserta yang hadir dalam setiap sesi rapat pembahasan. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan. 3. Pembelian Sampel Pembelian sampel produk inovasi pangan olahan yang digunakan sebagai bahan kajian dan pembahasan dalam proses fasilitasi standardisasi keamanan, mutu, dan manfaat produk. Sampel yang dibeli disesuaikan dengan kebutuhan pengujian dan pembahasan teknis yang dilaksanakan, dengan jenis dan jumlah sampel ditentukan berdasarkan kebutuhan riil kegiatan serta memperhatikan efisiensi dan efektivitas penggunaan anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2934721);
