INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66683923', 66683923, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Biaya Penginapan Perjalanan Dinas Biasa dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 7800000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Kegiatan ini merupakan pemberian biaya penginapan perjalanan dinas biasa kepada petugas/pegawai yang ditugaskan untuk melaksanakan tinjau lapang ke luar kota dalam rangka Fasilitasi Standardisasi Keamanan, Mutu dan Manfaat Produk Inovasi Pangan Olahan. Tinjau lapang dilakukan guna memperoleh data dan informasi langsung di lapangan yang diperlukan sebagai bahan kajian dalam proses fasilitasi standardisasi produk inovasi pangan olahan. Biaya penginapan disediakan untuk mendukung kelancaran pelaksanaan tugas selama petugas/pegawai berada di lokasi tinjau lapang.', 'Biaya penginapan yang diberikan kepada petugas/pegawai yang melaksanakan perjalanan dinas biasa dalam rangka tinjau lapang ke luar kota. Penginapan disediakan selama petugas/pegawai menjalankan tugas di lokasi tinjau lapang, dengan jumlah hari penginapan disesuaikan dengan durasi dan kebutuhan pelaksanaan kegiatan di lapangan. Fasilitas penginapan menggunakan hotel atau tempat menginap lainnya yang layak dan representatif sesuai dengan ketersediaan di wilayah tujuan. Besaran biaya penginapan mengacu pada Standar Biaya Masukan (SBM) yang berlaku berdasarkan wilayah/kota tujuan dan golongan pegawai yang bersangkutan, serta dibayarkan secara riil sesuai bukti pengeluaran dan ketentuan yang ditetapkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2935399);
