INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66686735', 66686735, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pertanian dan Ketahanan Pangan', 'Pemberian Pupuk HPT Pengembangan Kawasan Peternakan Unggulan Kab. Serdang Bedagai', 'Barang', 'Dikecualikan', 'Sumatera Utara, Serdang Bedagai (Kab.)', 42100000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Pemberian Pupuk HPT Pengembangan Kawasan Peternakan Unggulan Kab. Serdang Bedagai', 'Pemberian Pupuk HPT Pengembangan Kawasan Peternakan Unggulan Kab. Serdang Bedagai', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2936678);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66687340', 66687340, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Monitoring dan Evaluasi Pelaksanaan Anggaran Direktorat Standardisasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 5658000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan penyediaan belanja bahan dalam rangka mendukung pelaksanaan Monitoring dan Evaluasi Pelaksanaan Anggaran Direktorat Standardisasi Pangan Olahan. Bahan yang disediakan meliputi penjilidan dokumen satuan kerja, konsumsi makan siang, serta snack bagi peserta rapat yang diselenggarakan dalam rangka monitoring dan evaluasi pelaksanaan anggaran. Penyediaan bahan ini bertujuan untuk mendukung kelancaran proses monitoring dan evaluasi sehingga dapat menghasilkan laporan dan rekomendasi yang komprehensif terkait pelaksanaan anggaran direktorat.', '1. Penjilidan Dokumen Satker Penjilidan dokumen satuan kerja yang diperlukan dalam rangka monitoring dan evaluasi pelaksanaan anggaran Direktorat Standardisasi Pangan Olahan, meliputi penjilidan laporan keuangan, laporan kinerja, dokumen perencanaan, dan dokumen pendukung lainnya. Penjilidan dilakukan sesuai kebutuhan riil jumlah dokumen yang dihasilkan selama periode monitoring dan evaluasi, dengan biaya dibayarkan berdasarkan tarif riil jasa penjilidan yang berlaku dan memperhatikan prinsip efisiensi penggunaan anggaran. 2. Makan Siang Rapat Konsumsi makan siang yang disediakan bagi peserta rapat dalam rangka pelaksanaan monitoring dan evaluasi pelaksanaan anggaran Direktorat Standardisasi Pangan Olahan. Makan siang disediakan sesuai jumlah peserta yang hadir dengan menu memenuhi standar kelayakan dan kecukupan gizi. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan. 3. Snack Rapat Konsumsi snack yang disediakan bagi peserta rapat sebagai pendukung kelancaran jalannya rapat dalam rangka monitoring dan evaluasi pelaksanaan anggaran Direktorat Standardisasi Pangan Olahan. Snack disediakan sesuai jumlah peserta yang hadir dalam setiap pelaksanaan rapat. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2936679);
