INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66687238', 66687238, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Bahan dalam rangka Pengelolaan Data dan Informasi pada Direktorat Standardisasi Pangan Olahan', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 25920000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan penyediaan belanja bahan berupa konsumsi rapat dalam rangka mendukung pengelolaan data dan informasi pada Direktorat Standardisasi Pangan Olahan. Konsumsi yang disediakan meliputi makan siang dan snack bagi peserta rapat yang diselenggarakan di kantor dalam rangka pembahasan dan koordinasi terkait pengelolaan data dan informasi direktorat. Penyediaan konsumsi ini bertujuan untuk mendukung kelancaran pelaksanaan rapat sehingga proses pengelolaan data dan informasi dapat berjalan secara efektif.', '1. Makan Siang Rapat di Kantor Konsumsi makan siang yang disediakan bagi peserta rapat yang diselenggarakan di kantor dalam rangka pengelolaan data dan informasi Direktorat Standardisasi Pangan Olahan. Makan siang disediakan sesuai jumlah peserta yang hadir dengan menu memenuhi standar kelayakan dan kecukupan gizi. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan. 2. Snack Rapat di Kantor Konsumsi snack yang disediakan bagi peserta rapat yang diselenggarakan di kantor sebagai pendukung kelancaran jalannya rapat dalam rangka pengelolaan data dan informasi Direktorat Standardisasi Pangan Olahan. Snack disediakan sesuai jumlah peserta yang hadir dalam setiap pelaksanaan rapat. Besaran biaya mengacu pada Standar Biaya Masukan (SBM) yang berlaku untuk satuan orang/kali dan dibayarkan berdasarkan kebutuhan riil pelaksanaan kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2936804);
