INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66686759', 66686759, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'DEPUTI III BIDANG PENGAWASAN PANGAN OLAHAN', 'Belanja Barang Persediaan dalam rangka Pelaksanaan Operasional Kegiatan Standardisasi Pangan Olahan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 35100000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Kegiatan ini merupakan pengadaan belanja barang persediaan dalam rangka mendukung pelaksanaan operasional kegiatan Standardisasi Pangan Olahan. Barang persediaan yang diadakan meliputi kebutuhan pencetakan, alat tulis kantor, serta keperluan kantor lainnya yang dibutuhkan dalam menunjang kelancaran pelaksanaan tugas dan fungsi di bidang standardisasi pangan olahan. Pengadaan barang persediaan ini dilakukan secara berkala sesuai kebutuhan guna memastikan ketersediaan bahan dan perlengkapan operasional kantor secara memadai dan berkesinambungan.', '1. Pencetakan Pengadaan kebutuhan pencetakan berupa tinta printer, toner, kertas, dan bahan cetak lainnya yang diperlukan untuk mendukung operasional kegiatan standardisasi pangan olahan. Jenis dan jumlah bahan cetak yang diadakan disesuaikan dengan kebutuhan riil operasional, dengan memperhatikan prinsip efisiensi dan efektivitas penggunaan anggaran. 2. Alat Tulis Kantor Pengadaan alat tulis kantor yang diperlukan untuk mendukung kelancaran pelaksanaan operasional kegiatan standardisasi pangan olahan, meliputi antara lain pulpen, pensil, spidol, penggaris, stapler, map, binder, dan perlengkapan tulis kantor lainnya. Jenis dan jumlah alat tulis yang diadakan disesuaikan dengan kebutuhan riil pelaksanaan kegiatan dengan memperhatikan prinsip efisiensi penggunaan anggaran. 3. Keperluan Kantor Lainnya Pengadaan barang keperluan kantor lainnya yang dibutuhkan dalam menunjang operasional kegiatan standardisasi pangan olahan, meliputi antara lain bahan kebersihan, perlengkapan komputer, dan kebutuhan penunjang operasional kantor lainnya. Pengadaan dilakukan sesuai kebutuhan riil dengan memperhatikan ketersediaan barang dan prinsip efisiensi serta efektivitas penggunaan anggaran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2936830);
