INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66688725', 66688725, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Pengadaan Penunjang Imunisasi Buffer Stok Pusat Untuk Logistik Penunjang Vaksinasi Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 3918510830, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PT', 'Belanja Barang Persediaan Barang Konsumsi dengan Menyediakan Logistik Penunjang Vaksinasi Tahun 2026 berupa ADS 0,5 mL sebanyak 2.624.918 buah dengan estimasi harga satuan Rp1.278,50, ADS 5 mL sebanyak 328.115 buah dengan estimasi harga satuan Rp1.714,50', 'Spesifikasi Logistik Penunjang Vaksinasi sebagai berikut : A. AUTO DISABLE SYRINGE (ADS) 0,5 ML : 1 Bentuk ADS didesain khusus untuk program imunisasi. 2 Kapasitas isi 0,5 ml. 3 Graduation syringe 0,5 ml. 4 Bahan syringe Polypropylene warna putih transparan. Bebas PVC (Poly Vinyl Chloride). 5 Ukuran jarum 23 G atau 24 G atau 25 G x 1¼ inci atau 1 inci. 6 Kedudukan jarum Kedudukan jarum terpasang pada syringe. 7 Penutup jarum Setiap jarum dilengkapi dengan penutup untuk menjamin sterilitas. 8 Cara Kerja Saat piston ditarik sampai batas yang ditentukan maka secara otomatis vaksin yang diaspirasi adalah 0,5 ml (1 dosis) dan siap disuntikkan. Cara kerja penyuntikan: - Pada saat piston ditekan sampai vaksin habis (0,0 ml), maka piston akan terkunci (syringe lock) atau, - Pada saat piston ditekan sampai vaksin habis (0,0 ml), maka piston akan terkunci (syringe lock) dan bila piston ditarik kembali, piston akan patah atau, - Pada saat piston ditekan sampai vaksin habis (0,0 ml) maka piston dapat ditarik kembali, tetapi tidak dapat mengisap cairan. 9 Kemasan  Setiap ADS dikemas dengan pembungkus yang menjamin sterilitas syringe dan jarum.  Setiap 100-200 buah ADS dikemas dalam box yang terbuat dari kardus/ karton. Pada bagian luar box dicantumkan tulisan “Kementerian Kesehatan RI tahun 2026” dengan logo imunisasi. 10 Nomor serie (Lot), masa kadaluarsa, dan ukuran jarum Pada setiap kemasan ADS tercantum nomor serie (Lot), masa kadaluarsa dan ukuran jarum yang digunakan. Masa kadaluarsa sekurang-kurangnya 4 tahun pada saat barang diterima di pusat dan di Dinas Kesehatan Provinsi. 11 Kelengkapan Setiap box dilengkapi dengan lembar petunjuk pemakaian sebagai berikut: - Petunjuk pemakaian, ditempel/ tertera pada setiap box bagian luar - 1 (satu) lembar petunjuk pemakaian dengan ukuran kertas A4 dimasukan dalam setiap box. - Petunjuk pemakaian dibuat dalam Bahasa Indonesia dan bahasa lain. 12 Terdaftar  Telah terdaftar pada Ditjen Farmasi dan Alat Kesehatan dan telah mempunyai nomor Registrasi.  Terdaftar pada PQS (Performance, Quality, and Safety) WHO dan atau Standar Nasional Indonesia (SNI). B. AUTO DISABLE SYRINGE (ADS) 5 ML : 1 Bentuk ADS didesain khusus untuk program imunisasi. 2 Kapasitas isi 5,0 ml. 3 Graduation syringe 0,1 ml atau 0,2 ml atau 0,5 ml. 4 Bahan syringe Polypropylene warna putih transparan. Bebas PVC (Poly Vinyl Chloride). 5 Ukuran jarum 21 G x 1,5 inchi atau 22 G x 1,5 inchi. 6 Kedudukan jarum Kedudukan jarum terpasang pada syringe. 7 Penutup jarum Setiap jarum dilengkapi dengan penutup untuk menjamin sterilitas. 8 Cara Kerja Saat piston ditarik sampai batas yang ditentukan maka secara otomatis cairan yang diaspirasi adalah 5,0 ml dan siap dipindakan ke vial/ tempat lain, cara kerja. - Pada saat piston ditekan sampai vaksin habis (0,0 ml) maka piston akan terkunci (syringe lock) atau, - Pada saat piston ditekan sampai vaksin habis (0,0 ml) maka piston akan terkunci (syringe lock) dan bila piston ditarik kembali, piston akan patah atau, - Pada saat piston ditekan sampai vaksin habis (0,0 ml) maka piston dapat ditarik kembali, tetapi tidak dapat mengisap cairan. 9 Kemasan  Setiap ADS dikemas dengan pembungkus yang menjamin sterilitas syringe dan jarum.  Setiap 100-200 buah ADS dikemas dalam 1 box yang terbuat dari kardus/ karton Pada bagian luar box dicantumkan tulisan “Kementerian Kesehatan RI tahun 2026” dengan logo imunisasi. 10 Nomor serie (Lot), masa kadaluarsa, dan ukuran jarum Pada setiap kemasan ADS tercantum nomor serie (Lot), masa kadaluarsa dan ukuran jarum yang digunakan. Masa kadaluarsa sekurang-kurangnya 4 tahun pada saat barang diterima di pusat dan Dinas Kesehatan Provinsi. 11 Kelengkapan Setiap box dilengkapi dengan lembar petunjuk pemakaian sebagai berikut: - Petunjuk pemakaian, ditempel/ tertera pada setiap box bagian luar, - 1 (satu) lembar petunjuk pemakaian dengan ukuran kertas A4 dimasukan dalam setiap box. - Petunjuk pemakaian dibuat dalam Bahasa Indonesia dan bahasa lain. 12 Terdaftar  Telah terdaftar pada Ditjen Farmasi dan Alat Kesehatan dan telah mempunyai nomor Registrasi.  Terdaftar pada PQS (Performance, Quality, and Safety) WHO dan atau Standar Nasional Indonesia (SNI).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2937939);
